grant([Grants, "on", "any", "to", Users]) ->
    grant_int(parse_grants(Grants), any, parse_roles(Users));
grant([Grants, "on", Type, Bucket, "to", Users]) ->
    grant_int(parse_grants(Grants), {Type, Bucket}, parse_roles(Users));
grant([Grants, "on", Type, "to", Users]) ->
    grant_int(parse_grants(Grants), Type, parse_roles(Users));
grant(_) ->
    io:format("Usage: grant <permissions> on (<type> [bucket]|any) to <"
              "users>~n"),
    error.

revoke([Grants, "on", "any", "from", Users]) ->
    revoke_int(parse_grants(Grants), any, parse_roles(Users));
revoke([Grants, "on", Type, Bucket, "from", Users]) ->
    revoke_int(parse_grants(Grants), {Type, Bucket}, parse_roles(Users));
revoke([Grants, "on", Type, "from", Users]) ->
    revoke_int(parse_grants(Grants), Type, parse_roles(Users));
revoke(_) ->
    io:format("Usage: revoke <permissions> on <type> [bucket] from <use"
              "rs>~n"),
    error.

