pick_info_attrs(Arg) ->
    case
        lists:foldr(fun("-name", {As, Ps}) ->
                           {[name | As], Ps};
                       ("-type", {As, Ps}) ->
                           {[type | As], Ps};
                       ("-module", {As, Ps}) ->
                           {[module | As], Ps};
                       ("-value", {As, Ps}) ->
                           {[value | As], Ps};
                       ("-cache", {As, Ps}) ->
                           {[cache | As], Ps};
                       ("-status", {As, Ps}) ->
                           {[status | As], Ps};
                       ("-timestamp", {As, Ps}) ->
                           {[timestamp | As], Ps};
                       ("-options", {As, Ps}) ->
                           {[options | As], Ps};
                       (P, {As, Ps}) ->
                           {As, [P | Ps]}
                    end,
                    {[], []},
                    Arg)
    of
        {[], Rest} ->
            {[name, type, module, value, cache, status, timestamp,
              options],
             Rest};
        Other ->
            Other
    end.

