parse_ip_and_maybe_port(String, Hostname) ->
    case string:tokens(String, ":") of
        [IPStr, PortStr] ->
            case inet_parse:ipv4strict_address(IPStr) of
                {ok, IP} ->
                    try list_to_integer(PortStr) of
                        Port ->
                            {IP, Port}
                    catch
                        _:_ ->
                            {error, {bad_port, PortStr}}
                    end;
                _ when Hostname ->
                    case inet_gethost_native:gethostbyname(IPStr) of
                        {ok, _} ->
                            try list_to_integer(PortStr) of
                                Port ->
                                    {IPStr, Port}
                            catch
                                _:_ ->
                                    {error, {bad_port, PortStr}}
                            end;
                        _ ->
                            {error, {bad_ip, IPStr}}
                    end;
                _ ->
                    {error, {bad_ip, IPStr}}
            end;
        [IPStr] ->
            case inet_parse:ipv4strict_address(IPStr) of
                {ok, IP} ->
                    IP;
                _ when Hostname ->
                    case inet_gethost_native:gethostbyname(IPStr) of
                        {ok, _} ->
                            IPStr;
                        _ ->
                            {error, {bad_ip, IPStr}}
                    end;
                _ ->
                    {error, {bad_ip, IPStr}}
            end
    end.

